import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import { SearchIcon, AnalyticsIcon } from './components/Icons';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';
import type { Chat } from '@google/genai';

const ELITE_SYSTEM_INSTRUCTION = `You are the PRO-N-OS 179-Elite Accuracy Engine, a world-class sports quant analyst.

PHASE 1: INDIVIDUAL MATCHUP DELTA (IMD)
- Analyze player vs defender matchups. Look at height/weight deltas, speed metrics, and historical performance against specific schemes.
- Only suggest props where the "True Probability" exceeds 65%.

PHASE 2: ROSTER INTEGRITY
- Scrutinize usage. If a player's minutes are expected to drop due to injury, blowout risk, or rest, adjust all associated props DOWN.
- Audit late-breaking status via Google Search (tweets, beat reporters within last 60 mins).

PHASE 3: POSITIVE EV (Expected Value)
- Compare your generated line vs Vegas/Sharp lines. 
- Assign "Elite Signal" (isElite179: true) ONLY to picks with 90%+ Roster Stability and a clear Matchup Edge.

PHASE 4: STRUCTURED OUTPUT
- If the user asks for a game prediction, return strict JSON conforming to the predictionSchema.
- If the user asks for a specific player (e.g., Anthony Davis assists), use Google Search to find his last 5 games, current health, and opponent defensive rank. Provide a table of his recent stats vs his current prop line.`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  const [promptInput, setPromptInput] = useState('');

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, []);

  useEffect(() => {
    clearSelection();
  }, [selectedSport, clearSelection]);

  const addToVault = useCallback((newPrediction: Prediction, game: Game) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${game.id}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: game.homeTeam,
      awayTeam: game.awayTeam,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    setVault(prev => [entry, ...prev.filter(v => !v.id.startsWith(game.id))].slice(0, 4));
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;

    setMessages(prev => [...prev, { role: 'user', content: text }]);
    setIsReplying(true);
    setError(null);

    try {
        let currentChat = chat;
        if (!currentChat) {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            currentChat = ai.chats.create({ 
                model: 'gemini-3-pro-preview', 
                config: {
                    systemInstruction: ELITE_SYSTEM_INSTRUCTION,
                    tools: [{ googleSearch: {} }]
                } 
            });
            setChat(currentChat);
        }

        const response = await currentChat.sendMessage({ message: text });
        const responseText = response.text || "Data stream interrupted.";

        // Try to parse as JSON if it looks like a prediction object
        try {
            if (responseText.trim().startsWith('{')) {
                const parsed = JSON.parse(responseText);
                if (parsed.winner && parsed.confidence) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep engine sync lost. Market variance exceeded threshold." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  const handlePredict = useCallback(async (isRetry = false) => {
    if (!selectedGame) return;
    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const config: any = {
        systemInstruction: ELITE_SYSTEM_INSTRUCTION,
        responseSchema: predictionSchema,
        responseMimeType: 'application/json',
      };

      if (!isRetry) config.tools = [{ googleSearch: {} }];

      const newChat = ai.chats.create({ model: 'gemini-3-pro-preview', config });
      const response = await newChat.sendMessage({ 
        message: `PERFORM HIGH-FIDELITY SIMULATION: ${selectedGame.homeTeam} vs ${selectedGame.awayTeam}. Focus on Prop Accuracy and Individual Matchup Deltas. Identify the 3 sharpest props available based on current data streams.` 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, selectedGame);
      setMessages([{ role: 'model', content: parsed }]);
      setChat(newChat);
      setShowSuggestions(true);
    } catch (err: any) {
      setError("Deep sync failed. Market variance or roster data stream is currently unstable.");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame, addToVault]);

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-6 max-w-4xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex justify-between items-center">{error}</div>}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-8">
                        {/* Global Assistant Input */}
                        <div className="bg-zinc-950/80 border border-zinc-900 p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.05] transition-opacity">
                                <AnalyticsIcon className="w-48 h-48 text-white" />
                            </div>
                            <div className="relative z-10 text-center space-y-4 mb-8">
                                <h2 className="text-3xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-amber-200 to-amber-500">
                                    Deep Intelligence Command
                                </h2>
                                <p className="text-[10px] font-black uppercase tracking-[0.4em] text-zinc-500">
                                    Scrub Rosters • Analyze Props • Predict Outcomes
                                </p>
                            </div>
                            <form onSubmit={onPromptSubmit} className="relative z-10 max-w-xl mx-auto">
                                <div className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Ex: Anthony Davis assist projection for next game..."
                                        className="w-full bg-black border-2 border-zinc-800 rounded-2xl px-6 py-4 text-white focus:outline-none focus:border-amber-500/50 transition-all pr-16"
                                    />
                                    <button type="submit" className="absolute right-3 top-3 bg-amber-500 text-black p-2.5 rounded-xl hover:bg-amber-400 transition-colors shadow-lg shadow-amber-500/20">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </div>
                                <div className="flex flex-wrap justify-center gap-2 mt-4">
                                    {['L5 Performance', 'Roster Scratches', 'EV+ Odds', 'Matchup Deltas'].map(tag => (
                                        <button 
                                            key={tag} 
                                            type="button"
                                            onClick={() => setPromptInput(`Show me ${tag} for tonight's top games`)}
                                            className="text-[9px] font-black text-zinc-600 hover:text-amber-500 uppercase tracking-widest bg-zinc-900/50 px-3 py-1 rounded-full border border-zinc-800 transition-colors"
                                        >
                                            {tag}
                                        </button>
                                    ))}
                                </div>
                            </form>
                        </div>

                        <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />

                        {selectedGame && (
                            <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20">
                                <button onClick={() => handlePredict()} className="bg-gradient-to-r from-amber-500 to-orange-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.4)] transform hover:scale-105 transition-all flex items-center gap-3">
                                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                                    SYNC ROSTERS & SIMULATE
                                </button>
                            </div>
                        )}
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-4">
                        <button onClick={clearSelection} className="text-zinc-500 hover:text-white mb-2 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 transition-colors">
                             <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                             Return to Engine Feed
                        </button>
                        <ChatInterface 
                            messages={messages} 
                            isReplying={isReplying} 
                            onSendMessage={handleSendMessage} 
                            oddsFormat={settings.oddsFormat} 
                            pickSlip={pickSlip} 
                            onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} 
                        />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Analyze my slip risk based on current roster deltas and situational motivation. Is there a sharp edge here?"); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, memo } from 'react';
import type { ChatMessage, OddsFormat, PropBet } from '../types';
import { PredictionDisplay } from './PredictionDisplay';
import { SendIcon, LogoIcon } from './Icons';

interface ChatInterfaceProps {
    messages: ChatMessage[];
    isReplying: boolean;
    onSendMessage: (message: string) => void;
    oddsFormat: OddsFormat;
    onAnalyzeProp?: (prop: PropBet) => void;
    pickSlip?: PropBet[];
    onTogglePick?: (prop: PropBet) => void;
    onSearchPlayer?: (player: string) => void;
}

const renderMarkdownTable = (lines: string[], keyPrefix: string) => {
    // Filter out separator lines (e.g. |---|---|)
    const tableRows = lines.filter(line => !line.match(/^[|\-\s:]+$/) && line.includes('|'));

    if (tableRows.length < 2) return null;

    const headers = tableRows[0].split('|').filter(cell => cell.trim() !== '').map(c => c.trim());
    const dataRows = tableRows.slice(1).map(row => 
        row.split('|').filter(cell => cell.trim() !== '').map(c => c.trim())
    );

    return (
        <div key={`${keyPrefix}-table`} className="my-6 overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-950/50">
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-[10px] text-left">
                    <thead className="bg-zinc-900/80">
                        <tr>
                            {headers.map((header, idx) => (
                                <th key={idx} className="px-4 py-3 font-black text-zinc-500 uppercase tracking-widest whitespace-nowrap border-b border-zinc-800">
                                    {header}
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-900">
                        {dataRows.map((row, rowIdx) => (
                            <tr key={rowIdx} className="hover:bg-amber-500/[0.02] transition-colors">
                                {row.map((cell, cellIdx) => (
                                    <td key={cellIdx} className="px-4 py-3 text-zinc-300 font-medium whitespace-nowrap tabular-nums">
                                        {cell}
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

const renderBold = (text: string, key: string) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return (
        <span key={key}>
            {parts.map((part, index) => {
                if (part.startsWith('**') && part.endsWith('**')) {
                    return <strong key={index} className="text-amber-500 font-black">{part.slice(2, -2)}</strong>;
                }
                return part;
            })}
        </span>
    );
};

const renderModelContent = (content: string) => {
    const lines = content.split('\n');
    const elements: React.ReactNode[] = [];
    let tableBuffer: string[] = [];

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();

        if (line.startsWith('|') && (line.endsWith('|') || line.split('|').length > 1)) {
            tableBuffer.push(line);
        } else {
            if (tableBuffer.length > 0) {
                elements.push(renderMarkdownTable(tableBuffer, `table-${i}`));
                tableBuffer = [];
            }

            if (line !== '') {
                elements.push(
                    <p key={`p-${i}`} className="mb-3 last:mb-0 leading-relaxed text-zinc-300">
                        {renderBold(line, `bold-${i}`)}
                    </p>
                );
            }
        }
    }

    if (tableBuffer.length > 0) {
        elements.push(renderMarkdownTable(tableBuffer, `table-end`));
    }

    return elements;
};

export const ChatInterface: React.FC<ChatInterfaceProps> = memo(({ messages, isReplying, onSendMessage, oddsFormat, onAnalyzeProp, pickSlip, onTogglePick, onSearchPlayer }) => {
    const [text, setText] = useState('');
    const endOfMessagesRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endOfMessagesRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (text.trim()) {
            onSendMessage(text.trim());
            setText('');
        }
    };

    return (
        <div className="bg-zinc-950/90 backdrop-blur-xl rounded-[2.5rem] shadow-2xl border border-zinc-800 flex flex-col h-[75vh] max-h-[800px] overflow-hidden">
           {/* Terminal Header */}
           <div className="px-6 py-4 border-b border-zinc-900 bg-black/40 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Deep Sync Terminal</span>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-[8px] font-black text-zinc-700 uppercase">Latency: 14ms</span>
                </div>
           </div>

           <div className="flex-grow p-6 overflow-y-auto space-y-8 custom-scrollbar">
                {messages.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
                        <LogoIcon className="w-16 h-16 mb-4 text-zinc-700" />
                        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-700">Awaiting Signal Command</p>
                    </div>
                )}

                {messages.map((msg, index) => (
                    <div key={index} className={`flex gap-4 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        {msg.role === 'model' && (
                            <div className="flex-shrink-0 w-10 h-10 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                <LogoIcon className="w-6 h-6 text-amber-500" />
                            </div>
                        )}

                        <div className={`w-full ${msg.role === 'user' ? 'max-w-md' : 'max-w-2xl'}`}>
                            {typeof msg.content === 'object' ? (
                                <PredictionDisplay 
                                    prediction={msg.content} 
                                    oddsFormat={oddsFormat} 
                                    onAnalyzeProp={onAnalyzeProp}
                                    pickSlip={pickSlip}
                                    onTogglePick={onTogglePick}
                                    onSearchPlayer={onSearchPlayer}
                                />
                            ) : (
                                <div className={`px-5 py-4 rounded-3xl ${
                                    msg.role === 'user' 
                                        ? 'bg-zinc-100 text-black font-semibold ml-auto' 
                                        : 'bg-zinc-900/50 text-zinc-200 border border-zinc-800'
                                }`}>
                                    {msg.role === 'model' ? (
                                        <div className="text-[13px]">{renderModelContent(msg.content)}</div>
                                    ) : (
                                        <p className="whitespace-pre-wrap text-[13px] leading-relaxed">{msg.content}</p>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                ))}
                 {isReplying && (
                    <div className="flex gap-4 justify-start">
                        <div className="flex-shrink-0 w-10 h-10 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                             <LogoIcon className="w-6 h-6 text-amber-500" />
                        </div>
                        <div className="px-5 py-4 rounded-3xl bg-zinc-900/50 border border-zinc-800">
                            <div className="flex items-center gap-3">
                                <span className="w-2 h-2 bg-amber-500 rounded-full animate-bounce"></span>
                                <span className="w-2 h-2 bg-amber-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                                <span className="w-2 h-2 bg-amber-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                                <span className="text-[9px] font-black text-amber-500 uppercase tracking-widest ml-2">Grounding Search Results...</span>
                            </div>
                        </div>
                    </div>
                )}
                <div ref={endOfMessagesRef} />
            </div>

            <div className="p-6 border-t border-zinc-900 bg-black/20">
                <form onSubmit={handleSubmit} className="flex items-center gap-3">
                    <input
                        type="text"
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder="Ask about Anthony Davis, Giannis, or tonight's O/U sharp picks..."
                        disabled={isReplying}
                        className="w-full bg-zinc-900/50 border border-zinc-800 rounded-2xl px-6 py-4 text-sm text-white focus:outline-none focus:border-amber-500/50 transition-all disabled:opacity-50"
                    />
                    <button
                        type="submit"
                        disabled={isReplying || !text.trim()}
                        className="bg-amber-500 text-black rounded-2xl p-4 hover:bg-amber-400 disabled:bg-zinc-800 disabled:text-zinc-600 disabled:cursor-not-allowed transition-all shadow-lg shadow-amber-500/10"
                        aria-label="Send message"
                    >
                        <SendIcon className="w-6 h-6" />
                    </button>
                </form>
            </div>
        </div>
    );
});

import React, { useState, useEffect, memo, useMemo, useCallback } from 'react';
import type { Game } from '../types';
import { getSchedule } from '../services/geminiService';
import { AnalyticsIcon, LogoIcon } from './Icons';

interface GameScheduleProps {
  sport: string;
  selectedGame: Game | null;
  onSelectGame: (game: Game) => void;
}

const LOAD_SUB_MESSAGES = [
  "Auditing Market Liquidity...",
  "Scrubbing Active Roster Deltas...",
  "Verifying 179-Point Variance...",
  "Locking Elite Signal Feed..."
];

export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [loadMsgIdx, setLoadMsgIdx] = useState(0);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());

  const fetchGames = useCallback(async (quiet = false) => {
    if (!quiet) setIsLoading(true);
    else setIsRefreshing(true);

    setError(null);
    try {
      const fetchedGames = await getSchedule(sport);
      if (fetchedGames && fetchedGames.length > 0) {
        setGames(fetchedGames);
        setLastUpdated(new Date());
      } else if (!quiet) {
        setError(`No active ${sport} markets found.`);
      }
    } catch (err) {
      if (!quiet) setError('Satellite link lost.');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [sport]);

  useEffect(() => { fetchGames(); }, [sport, fetchGames]);

  useEffect(() => {
    const pollInterval = setInterval(() => fetchGames(true), 120000);
    return () => clearInterval(pollInterval);
  }, [fetchGames]);

  useEffect(() => {
    if (isLoading && games.length === 0) {
      const timer = setInterval(() => {
        setLoadMsgIdx((prev) => (prev + 1) % LOAD_SUB_MESSAGES.length);
      }, 1500);
      return () => clearInterval(timer);
    }
  }, [isLoading, games.length]);

  if (isLoading && games.length === 0) {
    return (
      <div className="py-24 flex flex-col items-center justify-center space-y-6">
        <div className="relative w-16 h-16">
          <div className="absolute inset-0 border-4 border-amber-500/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-t-amber-500 rounded-full animate-spin"></div>
        </div>
        <div className="text-center">
