const PropHistorySummary = memo(({ history }: { history: PerformanceGame[] }) => {
    if (!history || history.length === 0) return null;

    const hits = history.filter(h => h.hit).length;
    const winRate = Math.round((hits / history.length) * 100);
    const avgValue = (history.reduce((acc, curr) => acc + parseFloat(curr.actualValue.replace(/[^0-9.]/g, '') || '0'), 0) / history.length).toFixed(1);

    return (
        <div className="mt-4 flex flex-wrap gap-3">
            <div className="flex-1 min-w-[100px] bg-black/40 border border-white/5 rounded-2xl p-3 flex flex-col items-center justify-center">
                <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest mb-1">Win Rate (Line)</span>
                <span className={`text-sm font-black italic ${winRate >= 60 ? 'text-green-500' : 'text-amber-500'}`}>{winRate}%</span>
            </div>
            <div className="flex-1 min-w-[100px] bg-black/40 border border-white/5 rounded-2xl p-3 flex flex-col items-center justify-center">
                <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest mb-1">Avg Performance</span>
                <span className="text-sm font-black text-white italic">{avgValue}</span>
            </div>
            <div className="flex-[2] min-w-[180px] bg-black/40 border border-white/5 rounded-2xl p-3">
                <div className="flex justify-between items-center mb-1.5">
                    <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">Recent Delta (L5)</span>
                    <div className="flex gap-1">
                        {history.slice(0, 5).map((h, i) => (
                            <div 
                                key={i} 
                                className={`w-1.5 h-1.5 rounded-full ${h.hit ? 'bg-green-500' : 'bg-red-500'}`}
                                title={`${h.date}: ${h.actualValue} vs ${h.opponent}`}
                            ></div>
                        ))}
                    </div>
                </div>
                <div className="flex gap-1 justify-between">
                    {history.slice(0, 3).map((h, i) => (
                        <div key={i} className="text-center">
                            <div className="text-[8px] font-black text-zinc-400 tabular-nums">{h.actualValue}</div>
                            <div className="text-[6px] font-bold text-zinc-700 uppercase tracking-tighter truncate w-10">{h.opponent}</div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
});

