        setLastUpdated(new Date());
      } else if (!quiet) {
        setError(`No active ${sport} markets found in current data stream.`);
      }
    } catch (err) {
      if (!quiet) setError('Satellite link lost. Engine cannot reach market data.');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [sport]);

  useEffect(() => { fetchGames(); }, [sport, fetchGames]);

  useEffect(() => {
    // Polling every 60 seconds for "dynamic" updates of scores and statuses
    const pollInterval = setInterval(() => fetchGames(true), 60000);
    return () => clearInterval(pollInterval);
  }, [fetchGames]);

  useEffect(() => {
    if ((isLoading || isRefreshing) && games.length === 0) {
      const timer = setInterval(() => {
        setLoadMsgIdx((prev) => (prev + 1) % LOAD_SUB_MESSAGES.length);
      }, 1200);
      return () => clearInterval(timer);
    }
  }, [isLoading, isRefreshing, games.length]);

  if (isLoading && games.length === 0) {
    return (
      <div className="py-32 flex flex-col items-center justify-center space-y-8 animate-pulse">
        <div className="relative w-20 h-20">
          <div className="absolute inset-0 border-4 border-amber-500/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-t-amber-500 rounded-full animate-spin"></div>
          <div className="absolute inset-4 bg-amber-500/5 rounded-full blur-xl"></div>
        </div>
        <div className="text-center space-y-2">
          <div className="text-zinc-600 font-black uppercase text-[10px] tracking-[0.5em] mb-2">Deep Sync Active</div>
          <div className="text-amber-500 font-black uppercase text-xs tracking-[0.2em] animate-pulse">
            {LOAD_SUB_MESSAGES[loadMsgIdx]}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 w-full animate-fade-in">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center px-4 gap-4">
          <div className="flex items-center gap-3">
              <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.8)]"></div>
              <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.4em]">Tactical Feed: {sport}</h3>
          </div>
          <div className="flex items-center gap-4">
              <span className="text-[8px] font-black text-zinc-700 uppercase tracking-widest bg-zinc-950 px-3 py-1 rounded-full border border-zinc-900">
                Last Sync: {lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
              </span>
              <button 
                onClick={() => fetchGames(true)} 
                disabled={isRefreshing} 
                className={`text-[9px] font-black uppercase tracking-widest transition-all px-4 py-1.5 rounded-lg border flex items-center gap-2 ${
                  isRefreshing 
                    ? 'text-amber-500 border-amber-500/50 bg-amber-500/10 cursor-wait' 
                    : 'text-zinc-500 border-zinc-800 hover:text-amber-500 hover:border-amber-500/50 bg-black/40'
                }`}
              >
                  <LogoIcon className={`w-3 h-3 ${isRefreshing ? 'animate-spin' : ''}`} />
                  {isRefreshing ? 'Deep Scanning...' : 'Refresh Market'}
              </button>
          </div>
      </div>

      {error && (
        <div className="mx-4 p-8 bg-zinc-950/80 border-2 border-dashed border-zinc-900 rounded-[2.5rem] text-center">
            <span className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em] block mb-2">Feed Interruption</span>
            <p className="text-xs text-zinc-400 font-medium italic">{error}</p>
            <button onClick={() => fetchGames()} className="mt-4 text-[9px] font-black text-amber-500 uppercase underline tracking-widest">Retry Satellite Link</button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {games.map((game) => (
          <GameCard 
            key={game.id} 
            game={game} 
            isSelected={selectedGame?.id === game.id} 
            onSelectGame={onSelectGame} 
          />
        ))}
      </div>
    </div>
  );
});

