const PropHistorySummary = memo(({ history, line, type }: { history: PerformanceGame[], line: string, type: 'MORE' | 'LESS' }) => {
    if (!history || history.length === 0) return null;

    const hits = history.filter(h => h.hit).length;
    const winRate = Math.round((hits / history.length) * 100);
    const avgValue = (history.reduce((acc, curr) => acc + parseFloat(curr.actualValue.replace(/[^0-9.]/g, '') || '0'), 0) / history.length).toFixed(1);
    const lineNum = parseFloat(line);

    return (
        <div className="mt-4 p-4 bg-black/40 border border-white/5 rounded-2xl space-y-3">
            <div className="flex justify-between items-center">
                <div className="flex gap-4">
                    <div className="flex flex-col">
                        <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">Historical Hit %</span>
                        <span className={`text-xs font-black italic ${winRate >= 60 ? 'text-green-400' : 'text-amber-500'}`}>{winRate}% Accuracy</span>
                    </div>
                    <div className="flex flex-col">
                        <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">Avg Output</span>
                        <span className="text-xs font-black text-white italic">{avgValue}</span>
                    </div>
                </div>
                <div className="flex gap-1">
                    {history.slice(0, 5).reverse().map((h, i) => (
                        <div 
                            key={i} 
                            className={`w-2 h-6 rounded-sm transition-all duration-500 ${h.hit ? 'bg-green-500' : 'bg-zinc-800'} relative group/bar`}
                        >
                            <div className="absolute bottom-full mb-1 left-1/2 -translate-x-1/2 opacity-0 group-hover/bar:opacity-100 transition-opacity bg-zinc-900 border border-zinc-800 px-1.5 py-0.5 rounded text-[6px] font-black text-white z-20 whitespace-nowrap">
                                {h.actualValue} vs {h.opponent}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="flex items-center gap-2">
                <div className="flex-1 h-[2px] bg-zinc-900 relative">
                   <div 
                     className="absolute h-full bg-amber-500/50" 
                     style={{ 
                        left: '50%', 
                        width: `${Math.min(Math.abs(parseFloat(avgValue) - lineNum) * 5, 50)}%`,
                        transform: parseFloat(avgValue) > lineNum ? 'translateX(0)' : 'translateX(-100%)'
                     }}
                   ></div>
                   <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-1 h-3 bg-white"></div>
                </div>
                <span className="text-[8px] font-black text-zinc-500 uppercase">Avg Delta: {Math.abs(parseFloat(avgValue) - lineNum).toFixed(1)}</span>
            </div>
        </div>
    );
});

