export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `SEARCH COMMAND: Locate all active ${sport} games for ${today}. 

  CORE REQUIREMENTS:
  1. SCRAPE LIVE ODDS: Spread, Moneyline, and Total from sharp offshore and domestic markets.
  2. ROSTER VALIDATION: Search for any late-breaking "Questionable" or "Out" designations for key players.
  3. LIVE STATUS & SCORES: Identify if games are 'Scheduled', 'Live', or 'Finished'. If 'Live' or 'Finished', provide the current or final score (format: 'Home - Away').
  4. CONTEXT: Identify if the game is a "Must-Win," divisional rivalry, or carries playoff seeding weight.

  FORMAT: You MUST return a VALID JSON object. 
  JSON Structure: { "games": [{ "id": "uuid", "homeTeam": "full name", "awayTeam": "full name", "league": "${sport}", "time": "ET (e.g. 7:30 PM)", "date": "Today", "status": "Scheduled|Live|Finished", "score": "string (e.g. 102 - 98)", "isMustWin": boolean, "playoffImplications": "string", "keyRosterNotes": "e.g. Luka Doncic (Active), Kyrie Irving (GTD)", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  const configWithSearch = { 
    tools: [{ googleSearch: {} }],
    temperature: 0.1,
    responseMimeType: 'application/json'
  };

  try {
    const response = await callWithRetry(async () => {
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: configWithSearch as any
      });
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    const isQuota = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
    if (isQuota) {
      throw new Error("QUOTA_EXHAUSTED");
    }
    console.error("Schedule sync failed:", error);
    return [];
  }
};

